"""Stage 2 presentation fragments, consumed by build.py."""
from html import escape
def case_intro(name, eyebrow, title, description, domain):
    return f'<section class="wrap inner-intro"><div class="breadcrumb"><a href="index.html">Главная</a><span>/</span><a href="projects.html">Проекты</a><span>/</span>{name}</div><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p><div class="case-actions"><a class="text-link" href="https://{domain}/" target="_blank" rel="noopener noreferrer">Открыть {domain} ↗</a><a class="text-link" href="#screens">Посмотреть экраны ↓</a></div></section>'

def case_section(label, title, paragraphs):
    return '<section class="wrap case-overview"><div><span class="eyebrow">'+label+'</span><h2>'+title+'</h2></div><div>'+''.join('<p>'+p+'</p>' for p in paragraphs)+'</div></section>'

def screen(image, alt, caption):
    src = 'assets/' + escape(image, quote=True)
    label = escape('Рассмотреть экран: ' + alt + ' (новая вкладка)', quote=True)
    return (
        f'<figure class="case-screen"><a class="case34-screen-link" href="{src}" '
        f'target="_blank" rel="noopener" aria-label="{label}">'
        f'<img src="{src}" width="1265" height="712" alt="{escape(alt, quote=True)}" loading="lazy"></a>'
        f'<figcaption><span class="case34-original-caption">{caption}</span>'
        f'<a class="case34-zoom" href="{src}" target="_blank" rel="noopener">'
        'Рассмотреть экран <span>(новая вкладка)</span></a></figcaption></figure>'
    )

def case_mu56(btn):
    body = case_intro('Мир Улыбок','УСЛУГИ / САЙТ','Программы праздников.<br>Реальные фотографии.','Мир Улыбок — сайт детских праздников в Оренбурге. Программы, персонажи и фотографии для выбора подходящего формата.','mu56.ru')
    body += case_section('СОБСТВЕННЫЙ БИЗНЕС-ПРОЕКТ','Полный цикл<br>создания сайта.', ['Мир Улыбок — собственный бизнес Дмитрия Морозова. Сайт полностью создан им с нуля: от структуры и фотографий до реализации и оптимизации кода.','На сайте можно познакомиться с программами, посмотреть фотографии и выбрать формат. Первый экран связывает предложение, программу с ценой и переход к подбору праздника.'])
    body += case_section('ЗАЯВКИ И ИНТЕГРАЦИЯ','Сайт связан<br>с Telegram-ботом.', ['В проекте работает Telegram-бот. Интеграция дополняет сайт и процесс работы с обращениями.','Наличие интеграции подтверждено владельцем проекта. Этот кейс показывает полный цикл собственной разработки; рост продаж и количество обращений не заявляются.'])
    body += '<section class="soft-section"><div class="wrap section"><span class="eyebrow">ИНТЕРФЕЙС В ДЕТАЛЯХ</span><div class="case-observations"><article><span>01</span><h3>Предложение</h3><p>Первый экран называет услугу и показывает фотографию праздника.</p></article><article><span>02</span><h3>Выбор формата</h3><p>Кнопка подбора праздника и отдельный переход к трансформерам ведут к разным программам.</p></article><article><span>03</span><h3>Программы и цены</h3><p>Пакеты, персонажи и описание состава помогают сопоставить варианты.</p></article></div></div></section>'
    body += '<section class="wrap section" id="screens"><div class="section-heading"><div><span class="eyebrow">РЕАЛЬНЫЙ ЭКРАН</span><h2>От предложения<br>к выбору программы</h2></div></div>'+screen('mu56-home-desktop.jpg','Главная Мир Улыбок: фотографии детей с Бамблби, подбор праздника и программа с ценой','Публичная главная mu56.ru · снимок 11.10.2026. Цена и условия на экране относятся к дате съёмки.')+'</section>'
    body += case_section('ТЕХНИЧЕСКОЕ КАЧЕСТВО','Один настольный<br>лабораторный тест.', ['В предоставленном отчёте PageSpeed Insights от 8 октября 2026 года главная mu56.ru получила 100 по производительности, специальным возможностям, рекомендациям и поисковой оптимизации в режиме «Компьютер».','Данных реальных пользователей в отчёте нет. Оценки относятся к одному лабораторному тесту; результаты на телефонах, других страницах и при повторных измерениях могут отличаться.'])
    body += '<section class="wrap case-evidence"><details><summary>Посмотреть исходный отчёт <span>+</span></summary><img src="assets/mu56-pagespeed-desktop-2026-10-08.png" width="1280" height="661" alt="Предоставленный отчёт PageSpeed Insights mu56.ru от 8 октября 2026: четыре оценки 100 в настольном режиме" loading="lazy"><p>Снимок предоставленного отчёта, не новый замер.</p></details></section>'
    body += related([('websites','Разработка сайтов'),('redesign','Редизайн сайта'),('support','Поддержка и развитие')],btn('Обсудить сайт для ваших услуг','?service=websites'))
    return body

def case_pilotspace(btn):
    body = case_intro('PilotSpace','ОБУЧЕНИЕ / ВЕБ-ПРИЛОЖЕНИЕ','Тренажёр<br>для подготовки пилотов','Создан по запросу пилотов из Узбекистана, которым было неудобно готовиться по PDF.','pilotspace.ru')
    body += case_section('ПРОБЛЕМА И ЗАПРОС','От большого PDF —<br>к практике по темам.', ['Пилотам было неудобно готовиться по PDF с вопросами. Они попросили сделать интерактивные тесты: выбирать темы, отвечать в браузере и возвращаться к ошибкам.','PilotSpace — бесплатный самостоятельный тренажёр для повторения теоретических вопросов членами лётных экипажей. Материалы распределены по темам: системы Airbus и Boeing, аэродинамика, навигация, метеорология и правила полётов.'])
    body += case_section('РАЗРАБОТКА ПРОЕКТА','Самостоятельный<br>веб-инструмент.', ['Дмитрий Морозов развивает PilotSpace как самостоятельный проект. В основе интерфейса — короткая тренировка и возможность сосредоточиться на вопросах выбранной темы.'])
    body += '<section class="soft-section"><div class="wrap section"><div class="section-heading"><div><span class="eyebrow">РЕШЕНИЕ</span><h2>Учебный материал<br>в понятных сценариях</h2></div></div><div class="case-observations"><article><span>01</span><h3>Темы и тренировки</h3><p>Каталог вопросов, режим изучения и тренировки на 10, 20, 50 вопросов или свой диапазон.</p></article><article><span>02</span><h3>Работа над ошибками</h3><p>Неверные ответы, избранные вопросы и история тренировок помогают вернуться к нужному материалу.</p></article><article><span>03</span><h3>Прогресс и источники</h3><p>Сохранение прогресса в браузере, перенос через файл и ссылки на страницы исходного PDF.</p></article></div></div></section>'
    body += '<section class="wrap section screen-stack" id="screens"><div class="section-heading"><div><span class="eyebrow">РЕАЛЬНЫЕ ЭКРАНЫ</span><h2>Выбрать тему.<br>Перейти к вопросам.</h2></div></div>'+screen('pilotspace-home-desktop.jpg','Главная PilotSpace с выбором обучения и блоком работы над ошибками','Главная PilotSpace · реальный экран 11.10.2026.')+screen('pilotspace-training-settings.jpg','Настройки PilotSpace: раздел подготовки и система самолёта','Настройки новой тренировки · реальный экран 11.10.2026.')+screen('pilotspace-quiz-desktop.jpg','Первый вопрос тренировки PilotSpace с вариантами ответа','Тренировочный вопрос · реальный экран 11.10.2026.')+'</section>'
    body += case_section('РЕЗУЛЬТАТ','Доступный инструмент<br>для самостоятельных занятий.', ['Опубликован веб-тренажёр с тематическим каталогом, тренировками и работой над ошибками. По словам владельца, коллеги используют его для подготовки.','Сервис не заменяет действующие руководства и обучение и не является официальным экзаменом.'])
    return body + related([('applications','Веб-приложения'),('automation','Работа с данными и процессами')],btn('Обсудить веб-приложение для вашей задачи','?service=applications'))

def related(links, cta):
    return '<section class="wrap section case-related"><span class="eyebrow">СВЯЗАННЫЕ НАПРАВЛЕНИЯ</span><div class="case-related-links">'+''.join(f'<a href="{slug}.html"><span>{name}</span><span aria-hidden="true">↗</span></a>' for slug,name in links)+'</div>'+cta+'</section>'

def approach(intro, btn):
    stages = [('Разбираем задачу','Короткий бриф, текущая ситуация и ограничения.','Описание задачи, список пользователей и ключевых сценариев.'),('Согласуем решение','Структура, прототип, функции и границы первой версии.','Согласованное задание, смета, этапы и критерии приёмки.'),('Разрабатываем','Рабочие версии и демонстрация согласованных сценариев.','Версия для проверки на тестовой площадке и список выполненных работ.'),('Проверяем вместе','Формы, ссылки, роли и основные действия на компьютере и телефоне.','Перечень проверок, согласованные правки и готовность к запуску.'),('Запускаем и передаём','Переключение на рабочую версию по согласованному плану.','Исходники и доступы по договору, инструкция и порядок дальнейшей поддержки.')]
    body = intro('Подход','Понятные этапы.<br>Проверяемый результат.','На каждом этапе согласуем не только действия, но и то, что вы получите. Состав, сроки и стоимость фиксируем до начала разработки.')
    body += '<section class="wrap section compact approach-stages">'+''.join(f'<article><span class="eyebrow">0{i+1} / ЭТАП</span><div><h2>{title}</h2><p>{work}</p></div><div><span class="eyebrow">НА ВЫХОДЕ</span><p>{result}</p></div></article>' for i,(title,work,result) in enumerate(stages))+'</section>'
    body += case_section('ДОГОВОРЁННОСТИ','Цена, этапы<br>и порядок приёмки.', ['Не каждый небольшой сайт требует большого отдельного этапа проектирования. Его объём соразмерен задаче и фиксируется до работы.','Предлагаем оплату 30% после договора, 40% после согласования рабочей версии и 30% после итоговой проверки перед передачей. Для крупных задач согласуем этапы отдельно. Домен, хостинг, лицензии и подписки оплачиваются отдельно.'])
    body += case_section('СОГЛАСОВАНИЕ','Изменения —<br>с понятными границами.', ['Правки в согласованном объёме и новые пожелания различаем до выполнения. Если появляются дополнительные функции, сначала обсуждаем их влияние на стоимость и сроки.','После запуска в течение 30 календарных дней исправляем без доплаты ошибки в согласованном функционале. Новые функции и регулярное сопровождение оцениваем отдельно.'])
    return body + '<section class="wrap section compact">'+btn('Обсудить этапы вашего проекта')+'</section>'

